UniqueFd(const UniqueFd&) = delete;
UniqueFd& operator=(const UniqueFd&) = delete;

UniqueFd(UniqueFd&& other) noexcept : fd_(other.release()) {}

UniqueFd& operator=(UniqueFd&& other) noexcept {
  if (this != &other) {
    reset(other.release());
  }
  return *this;
}

void reset(int replacement = -1) noexcept {
  if (replacement == fd_) {
    return;
  }
  if (fd_ >= 0) {
    // On Linux, close() may report EINTR, but the descriptor is nevertheless
    // released; retrying could close an unrelated descriptor that reused the
    // same number. Preserve the caller's errno so RAII cleanup never clobbers
    // a diagnostic value the caller still needs.
    const int saved_errno = errno;
    ::close(fd_);
    errno = saved_errno;
  }
  fd_ = replacement;
}

bool init() {
    epoll_.reset(::epoll_create1(EPOLL_CLOEXEC));
    if (!epoll_.valid()) return false;
    wake_.reset(::eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC));
    if (!wake_.valid()) return false;
    epoll_event event{};
    event.events = EPOLLIN;
    event.data.u64 = 0; // Registration IDs start at 1; 0 belongs to wake.
    return ::epoll_ctl(epoll_.get(), EPOLL_CTL_ADD, wake_.get(), &event) == 0;
}

std::unique_ptr<StudyReactor> make_epoll_reactor() {
    auto reactor = std::make_unique<EpollReactor>();
    if (!reactor->init()) return nullptr;
    return reactor;
}

std::optional<Registration> watch(const Socket& socket, unsigned interest) override {
    const auto id = registrations_.add(socket.native(), interest);
    if (!id) return std::nullopt;
    if (interest != 0 && !control(EPOLL_CTL_ADD, socket.native(), *id, interest)) {
        registrations_.remove(*id); // Roll back membership, never reuse the spent ID.
        return std::nullopt;
    }
    return id;
}

bool control(int operation, int fd, Registration id, unsigned interest) {
    epoll_event event{};
    if (interest & Read) event.events |= EPOLLIN | EPOLLRDHUP;
    if (interest & Write) event.events |= EPOLLOUT;
    event.data.u64 = id;
    return ::epoll_ctl(epoll_.get(), operation, fd, &event) == 0;
}

bool change(Registration id, unsigned interest) override {
    const auto* entry = registrations_.find(id);
    if (!entry || (interest & ~kInterestMask) != 0) return false;
    const auto old = entry->interest;
    if (old == interest) return true;
    // A paused registration stays in our table, but not in epoll's interest list.
    const int operation = old == 0 ? EPOLL_CTL_ADD :
                          interest == 0 ? EPOLL_CTL_DEL : EPOLL_CTL_MOD;
    if (!control(operation, entry->fd, id, interest)) return false;
    return registrations_.modify(id, interest); // Non-allocating commit after OS success.
}

bool unwatch(Registration id) override {
    const auto* entry = registrations_.find(id);
    if (!entry) return false;
    if (entry->interest != 0 && !control(EPOLL_CTL_DEL, entry->fd, id, 0)) return false;
    return registrations_.remove(id);
}
bool current(Registration id) const override { return registrations_.find(id) != nullptr; }

ReadyBatch poll(int timeout_ms) override {
    ReadyBatch result;
    result.events.reserve(Registrations::capacity);
    if (timeout_ms < 0 || timeout_ms > 1000) {
        result.state = PollState::error; result.error = EINVAL; return result;
    }
    const int count = ::epoll_wait(epoll_.get(), scratch_.data(),
                                  static_cast<int>(scratch_.size()), timeout_ms);
    if (count == 0) return result;
    if (count < 0) {
        result.error = errno;
        result.state = result.error == EINTR ? PollState::interrupted : PollState::error;
        return result;
    }

    const auto* entry = registrations_.find(id);
    if (!entry || entry->interest == 0) continue;
    const bool fault = (event.events & (EPOLLERR | EPOLLHUP)) != 0;
    result.events.push_back({id, (event.events & (EPOLLIN | EPOLLRDHUP)) != 0 || fault,
                             (event.events & EPOLLOUT) != 0, fault});
}
return result; // Removal after return still requires dispatch-time validation.

void zero_mask_is_not_pause() {
    int ends[2];require(::pipe2(ends,O_NONBLOCK|O_CLOEXEC)==0,"pipe");
    UniqueFd reader(ends[0]),writer(ends[1]),epoll(::epoll_create1(EPOLL_CLOEXEC));
    epoll_event wanted{};wanted.data.u64=9; // Deliberately request no normal interests.
    require(::epoll_ctl(epoll.get(),EPOLL_CTL_ADD,reader.get(),&wanted)==0,"zero mask add");
    require(::write(writer.get(),"hi",2)==2,"bytes before hangup");
    writer.reset();epoll_event event{};
    require(::epoll_wait(epoll.get(),&event,1,0)==1&&(event.events&EPOLLHUP),"HUP not masked by zero interest");
    char remaining[2];require(::read(reader.get(),remaining,2)==2,"HUP can coexist with unread bytes");
    require(::epoll_ctl(epoll.get(),EPOLL_CTL_DEL,reader.get(),nullptr)==0,"detach paused");
    require(::epoll_wait(epoll.get(),&event,1,0)==0,"DEL actually stops observation");
}

void raw_trigger(bool edge, bool oneshot) {
    int ends[2]; require(::pipe2(ends,O_NONBLOCK|O_CLOEXEC)==0,"pipe");
    UniqueFd read_end(ends[0]),write_end(ends[1]),epoll(::epoll_create1(EPOLL_CLOEXEC));
    require(epoll.valid(),"epoll");
    epoll_event wanted{}; wanted.events=EPOLLIN|(edge?EPOLLET:0u)|(oneshot?EPOLLONESHOT:0u);
    wanted.data.u64=77;
    require(::epoll_ctl(epoll.get(),EPOLL_CTL_ADD,read_end.get(),&wanted)==0,"raw add");
    require(::write(write_end.get(),"abcdefgh",8)==8,"pipe data already queued");
    epoll_event event{};
    require(::epoll_wait(epoll.get(),&event,1,0)==1&&event.data.u64==77,"initial ready identity");
    char bytes[8]; require(::read(read_end.get(),bytes,1)==1,"partial read");
    const int again=::epoll_wait(epoll.get(),&event,1,0);
    require(again==((edge||oneshot)?0:1),"LT repeats, ET/oneshot do not repeat this unchanged pipe");

    if(oneshot) {
        require(::epoll_ctl(epoll.get(),EPOLL_CTL_MOD,read_end.get(),&wanted)==0,"rearm");
        require(::epoll_wait(epoll.get(),&event,1,0)==1,"rearm observes remaining bytes");
    }
    require(::read(read_end.get(),bytes,7)==7,"remaining seven bytes");
    require(::read(read_end.get(),bytes,1)==-1&&errno==EAGAIN,"drained to would block");
    require(::epoll_ctl(epoll.get(),EPOLL_CTL_DEL,read_end.get(),nullptr)==0,"raw remove");
    require(::write(write_end.get(),"z",1)==1,"new input after remove");
    require(::epoll_wait(epoll.get(),&event,1,0)==0,"removed entry absent");
}

bool wake() noexcept override {
    const int saved_errno = errno;
    const std::uint64_t one = 1;
    ssize_t sent;
    do { sent = ::write(wake_.get(), &one, sizeof(one)); }
    while (sent < 0 && errno == EINTR);
    const bool notified = sent == sizeof(one) || (sent < 0 && errno == EAGAIN);
    errno = saved_errno;
    return notified;
}

if (id == 0) {
    result.woken = true;
    std::uint64_t pending;
    ssize_t read;
    do { read = ::read(wake_.get(), &pending, sizeof(pending)); }
    while (read < 0 && errno == EINTR);
    // One successful read absorbs the current counter. Concurrent writers
    // may leave a new notification for the next poll; do not drain forever.
    if (read != sizeof(pending) && !(read < 0 && errno == EAGAIN)) {
        result.state = PollState::error; result.error = read < 0 ? errno : EIO;
        return result;
    }
    continue;
}

void control_failures() {
    auto reactor=make_epoll_reactor();require(bool(reactor),"factory");auto sockets=pair();
    fail_operation=EPOLL_CTL_ADD;
    require(!reactor->watch(sockets.receiver,Read),"failed ADD rejected");
    auto id=reactor->watch(sockets.receiver,Read);
    require(id&&*id==2,"failed ADD consumed ID but released slot and fd membership");
    send(sockets.sender,7);observe_until(*reactor,1);
    fail_operation=EPOLL_CTL_DEL;
    require(!reactor->change(*id,0)&&reactor->current(*id),"failed pause preserves old membership");
    require(observe_until(*reactor,1).events[0].id==*id,"old read interest still active");
    require(reactor->change(*id,0),"pause after failed DEL");
    fail_operation=EPOLL_CTL_ADD;
    require(!reactor->change(*id,Read)&&reactor->poll(0).state==PollState::timeout,"failed resume stays paused");
    require(reactor->change(*id,Read),"resume success");
    fail_operation=EPOLL_CTL_MOD;
    require(!reactor->change(*id,Write),"failed MOD");
    auto unchanged=observe_until(*reactor,1);require(unchanged.events[0].readable&&!unchanged.events[0].writable,"failed MOD keeps original read mask");
    fail_operation=EPOLL_CTL_DEL;
    require(!reactor->unwatch(*id)&&reactor->current(*id),"failed removal stays registered");
    require(reactor->unwatch(*id)&&!reactor->current(*id),"removal succeeds on retry");
}

inline std::unique_ptr<StudyReactor> choose_reactor(bool epoll) {
    if (!epoll) return make_poll_reactor();
#if defined(__linux__)
    return make_epoll_reactor();
#else
    throw std::runtime_error("epoll requires Linux");
#endif
}
